-- Learn: progressive-learning notebooks (sessions) made of ordered markdown entries.
-- Purely additive: two new tables, no changes to existing ones. Safe to re-run.
--
-- Back up first (from MRTN-LAPPS):
--   pg_dump -h 10.0.0.225 -U kc_user -d kc_db -Fc -f ~/kc_db_backup_YYYYMMDD.dump
-- Apply:
--   psql -h 10.0.0.225 -U kc_user -d kc_db -f SQL/create_learn_tables.sql

CREATE TABLE IF NOT EXISTS "LearnSessions" (
    "SessionId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" VARCHAR(200) NOT NULL,
    "Topic" VARCHAR(200),
    -- Optional Knowledge Node the session is filed under (a label only; Learn never
    -- reads or writes Logs). SET NULL so deleting a node keeps working exactly
    -- as it does today instead of being blocked by a session that points at it.
    "NodeId" INTEGER NULL,
    "CreatedAt" TIMESTAMP NOT NULL DEFAULT now(),
    "UpdatedAt" TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT "FK_LearnSessions_KnowledgeNodes" FOREIGN KEY ("NodeId")
        REFERENCES "KnowledgeNodes" ("Id") ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS "LearnEntries" (
    "EntryId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SessionId" INTEGER NOT NULL,
    -- Gapped integer ordering (new entries land 65536 apart; inserts take the midpoint
    -- of their neighbours and the session is renumbered when a gap runs out).
    "Position" BIGINT NOT NULL,
    -- Raw markdown. Entry type, question status and @answers links are all
    -- parsed from this, never stored separately.
    "Source" TEXT NOT NULL,
    "CreatedAt" TIMESTAMP NOT NULL DEFAULT now(),
    "UpdatedAt" TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT "FK_LearnEntries_LearnSessions" FOREIGN KEY ("SessionId")
        REFERENCES "LearnSessions" ("SessionId") ON DELETE CASCADE,
    -- Deferred so a renumber can shuffle positions within one statement.
    CONSTRAINT "UQ_LearnEntries_SessionPosition" UNIQUE ("SessionId", "Position")
        DEFERRABLE INITIALLY DEFERRED
);
